  23         }
  24     }
  25 
  26     async save(user: UserProfile): Promise<Result<User, UserError>> {
  27         try {
  28             const data = this.toPersistence(user);
  29             await db.insert(users).values(data).onConflictDoUpdate({
  30                 target: users.id,
  31                 set: data,
  32             });
  33             return Result.ok(new User(user));
  34         } catch (error: any) {
  35             return Result.fail(UserError.internal(error.message));
  36         }
