  42             await db.update(users)
  43                 .set({ ...persistenceData, updatedAt: new Date().toISOString() })
  44                 .where(eq(users.id, id));
  45             return this.getById(id);
  46         } catch (error: any) {
  47             return Result.fail(UserError.internal(error.message));
  48         }
  49     }
