  54             return Result.ok();
  55         } catch (error: any) {
  56             return Result.fail(UserError.internal(error.message));
  57         }
  58     }
  59 
  60     async deductCredits(id: string, amount: number): Promise<Result<number, UserError>> {
  61         try {
  62             if (id === 'guest') {
  63                 return Result.ok(0);
  64             }
  65 
  66             // better-sqlite3 transactions are synchronous in Drizzle
  67             return db.transaction((tx) => {
  68                 const user = tx.select().from(users).where(eq(users.id, id)).get();
  69 
  70                 if (!user) {
  71                     return Result.fail(UserError.notFound("User not found"));
  72                 }
  73 
  74                 let currentCredits = user.credits ?? 0;
  75                 const lastUpdate = user.lastDailyCreditUpdate ? new Date(user.lastDailyCreditUpdate).getTime() : 0;
  76                 const twentyFourHours = 24 * 60 * 60 * 1000;
  77 
  78                 const updates: any = {};
  79 
  80                 if (Date.now() - lastUpdate > twentyFourHours) {
  81                     if (currentCredits < 10) {
  82                         currentCredits = 10;
  83                         updates.credits = currentCredits;
  84                     }
  85                     updates.lastDailyCreditUpdate = new Date().toISOString();
  86                 }
  87 
  88                 if (currentCredits < amount) {
  89                     return Result.fail(UserError.validation("Insufficient credits. Please purchase more credits to continue."));
  90                 }
  91 
  92                 const newBalance = currentCredits - amount;
  93                 updates.credits = newBalance;
  94                 updates.updatedAt = new Date().toISOString();
  95 
  96                 tx.update(users).set(updates).where(eq(users.id, id)).run();
  97                 return Result.ok(newBalance);
  98             });
  99         } catch (error: any) {
 100             return Result.fail(UserError.internal(error.message));
 101         }
